export const GLOSSARY_SHARD = Object.freeze({"bitcoin-halving":{"slug":"bitcoin-halving","cat":"basics","en":"Bitcoin halving","contentLocale":"id","term":"Bitcoin halving","aka":["halving","halving Bitcoin"],"short":"Bitcoin halving adalah peristiwa terjadwal kira-kira setiap empat tahun, atau tepatnya setiap 210.000 blok, ketika imbalan blok untuk penambang dipotong setengah.","body":[[["Bitcoin","bitcoin"]," baru masuk ke peredaran lewat imbalan blok yang diterima penambang. Aturan di kode Bitcoin memotong imbalan ini menjadi setengah setiap 210.000 blok. Pada awalnya imbalannya 50 BTC per blok, lalu turun menjadi 25, 12,5, 6,25, dan sejak halving April 2024 menjadi 3,125 BTC."],"Akibatnya, laju bertambahnya suplai Bitcoin terus melambat hingga batas 21 juta koin tercapai. Bagi penambang, halving berarti pendapatan dalam BTC dari imbalan blok langsung berkurang setengah, sehingga penambang dengan biaya listrik tinggi bisa tertekan.","Banyak orang mengaitkan halving dengan siklus harga. Namun hubungan itu tidak pasti karena harga juga dipengaruhi suku bunga, arus ETF, regulasi, dan sentimen. Anggap halving sebagai perubahan suplai yang sudah diketahui jauh hari, bukan sinyal harga otomatis."],"example":"Sebelum April 2024, setiap blok menghasilkan 6,25 BTC baru. Dengan rata-rata sekitar 144 blok per hari, itu berarti sekitar 900 BTC baru per hari. Setelah halving, imbalannya 3,125 BTC per blok, sehingga suplai baru turun menjadi sekitar 450 BTC per hari. Penambang yang sebelumnya menerima 0,5 BTC per hari dari imbalan blok kini hanya menerima sekitar 0,25 BTC, belum termasuk biaya transaksi.","mistakes":["Menganggap harga pasti naik setelah halving hanya karena pernah terjadi sebelumnya.","Mengira halving memotong jumlah BTC yang sudah Anda miliki, padahal yang dipotong hanya imbalan blok untuk penambang.","Mengira halving terjadi pada tanggal kalender pasti, padahal ditentukan oleh nomor blok."],"faq":[{"q":"Kapan Bitcoin halving berikutnya?","a":"Halving berikutnya terjadi setelah 210.000 blok sejak halving April 2024, yang biasanya diperkirakan sekitar 2028. Tanggal tepatnya bergantung pada kecepatan pembuatan blok."},{"q":"Apa dampak halving bagi pemegang BTC?","a":"Saldo Anda tidak berubah. Yang berubah adalah laju penerbitan BTC baru, yang menjadi setengahnya, sementara dampak ke harga tidak bisa dipastikan."}],"title":"Apa itu Bitcoin halving? Arti dan dampaknya","description":"Pelajari apa itu Bitcoin halving, kenapa imbalan blok dipotong setengah, dan apa artinya bagi suplai, penambang, dan pemegang BTC.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) adalah aset kripto pertama yang diluncurkan pada 2009, berjalan di jaringan terdesentralisasi dengan proof of work dan jumlah maksimal 21 juta koin."],["mining","Mining (penambangan kripto)","Mining atau penambangan kripto adalah proses memakai daya komputasi untuk memvalidasi transaksi dan menambahkan blok baru pada blockchain proof of work, dengan imbalan koin baru dan biaya transaksi."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan."],["hash-rate","Hash rate","Hash rate adalah total daya komputasi yang dipakai penambang untuk mengamankan blockchain proof of work seperti Bitcoin, diukur dalam jumlah tebakan hash per detik."],["satoshi","Satoshi (sats)","Satoshi atau sats adalah satuan terkecil Bitcoin, di mana 1 BTC sama dengan 100.000.000 satoshi."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"stop-loss":{"slug":"stop-loss","cat":"trading","en":"Stop-loss order","contentLocale":"id","term":"Stop loss","aka":["SL","cut loss","order stop loss"],"short":"Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana.","body":[["Stop loss memiliki harga pemicu (trigger). Saat ",["harga terakhir","last-price"]," atau ",["mark price","mark-price"]," menyentuh pemicu itu, exchange mengirim order penutupan, biasanya ",["market order","market-order"]," atau ",["limit order","limit-order"]," tergantung jenis yang Anda pilih. Banyak trader Indonesia menyebut tindakan ini cut loss."],["Stop market lebih pasti tereksekusi, tetapi bisa mengalami ",["slippage","slippage"]," saat harga melompat. ",["Stop limit","stop-limit-order"]," memberi kendali harga, tetapi berisiko tidak terisi jika harga melewati level limit dengan cepat. Exchange juga bisa berbeda dalam memilih harga acuan pemicu, jadi periksa pengaturannya."],"Letakkan stop loss di level yang membuktikan analisis Anda salah, bukan sekadar angka bulat. Lalu hitung ukuran posisi dari jarak stop itu. Pada futures, stop loss sebaiknya jauh sebelum harga likuidasi agar Anda yang menentukan kerugian, bukan mesin likuidasi."],"example":"Misalkan modal Anda 2.000 USDT dan Anda hanya mau rugi 1%, yaitu 20 USDT per transaksi. Anda membeli SOL di 160 USDT dengan stop loss di 152 USDT, jarak 8 USDT atau 5%. Ukuran posisinya 20 / 8 = 2,5 SOL, senilai 400 USDT. Jika stop tersentuh dan tereksekusi di 151,8 USDT karena slippage, kerugian Anda sekitar 20,5 USDT ditambah biaya.","mistakes":["Menggeser stop loss makin jauh setiap kali harga mendekatinya.","Memasang stop loss tepat di angka bulat yang mudah tersentuh oleh pergerakan biasa.","Mengira stop loss menjamin harga keluar persis di level pemicu."],"faq":[{"q":"Apa beda stop loss dan cut loss?","a":"Stop loss adalah order otomatis yang dipasang sebelumnya. Cut loss adalah tindakan menjual rugi, bisa secara manual atau lewat stop loss."},{"q":"Di mana sebaiknya memasang stop loss?","a":"Di level harga yang menunjukkan alasan Anda masuk sudah tidak berlaku, misalnya di bawah support penting, lalu sesuaikan ukuran posisi dengan jarak itu."}],"title":"Apa itu stop loss? Arti dan cara memasangnya","description":"Arti stop loss di trading kripto, beda stop market dan stop limit, dan cara menghitung ukuran posisi dari jarak stop.","related":[["take-profit","Take profit","Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan."],["stop-limit-order","Stop limit order","Stop limit order adalah order yang aktif saat harga menyentuh harga stop, lalu otomatis memasang limit order di harga limit yang Anda tentukan."],["trailing-stop","Trailing stop","Trailing stop adalah stop order yang otomatis mengikuti harga ketika bergerak menguntungkan Anda dengan jarak tetap, lalu menutup posisi ketika harga berbalik sejauh jarak itu."],["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit dan stop-loss adalah rencana, bukan asuransi"},"coin":null,"tool":"/liquidations","cta":false},"unrealized-pnl":{"slug":"unrealized-pnl","cat":"derivatives","en":"Unrealized PnL","contentLocale":"id","term":"Unrealized PnL (laba/rugi belum terealisasi)","aka":["unrealized PnL","floating profit","floating loss","PnL belum terealisasi"],"short":"Unrealized PnL adalah keuntungan atau kerugian di atas kertas dari posisi yang masih terbuka, dihitung dari selisih harga masuk dan harga acuan saat ini, dan baru menjadi nyata setelah posisi ditutup.","body":[["Selama ",["posisi terbuka","open-interest"],", angka unrealized PnL terus berubah mengikuti harga. Di futures, kebanyakan exchange menghitungnya memakai ",["mark price","mark-price"],", bukan ",["harga transaksi terakhir","last-price"],". Saat posisi ditutup, angka itu berubah menjadi realized PnL dan masuk ke saldo setelah dikurangi biaya."],["Unrealized PnL memengaruhi margin Anda. Di ",["mode cross","cross-margin"]," margin, keuntungan belum terealisasi dari satu posisi ikut menopang posisi lain, dan kerugian belum terealisasi mengurangi saldo yang tersedia. Beberapa exchange bahkan mengizinkan sebagian unrealized profit dipakai untuk membuka posisi baru, yang bisa memperbesar risiko."],["Exchange juga sering menampilkan ROE atau ROI, yaitu unrealized PnL dibagi margin. Angka persentase ini terlihat besar saat ",["leverage","leverage"]," tinggi, jadi perhatikan juga nilai absolutnya dalam ",["USDT","usdt"],"."]],"example":"Anda long 0,2 BTC di 62.500 USDT dengan margin 2.500 USDT, leverage 5x. Mark price sekarang 65.000. Unrealized PnL Anda = 0,2 x (65.000 - 62.500) = 500 USDT, dan ROE yang tampil 500 dibagi 2.500 = 20%. Jika Anda tidak menutup posisi dan harga kembali ke 61.000, unrealized PnL berubah menjadi 0,2 x (61.000 - 62.500) = -300 USDT. Keuntungan 500 USDT tadi tidak pernah benar-benar Anda terima.","mistakes":["Menganggap floating profit sudah menjadi uang Anda sebelum posisi ditutup.","Membuka posisi baru dengan memanfaatkan unrealized profit di cross margin sehingga risiko total membesar.","Terpaku pada ROE persentase tinggi tanpa melihat nilai PnL dalam USDT."],"faq":[{"q":"Apa beda unrealized PnL dan realized PnL?","a":"Unrealized PnL adalah untung atau rugi posisi yang masih terbuka dan bisa berubah. Realized PnL adalah hasil yang sudah terkunci setelah posisi ditutup, termasuk biaya dan funding."},{"q":"Kenapa unrealized PnL saya berbeda dari hitungan dengan harga di grafik?","a":"Karena kebanyakan exchange futures memakai mark price untuk menghitung unrealized PnL, sedangkan grafik menampilkan harga transaksi terakhir."}],"title":"Apa itu unrealized PnL? Arti floating profit dan loss","description":"Pahami unrealized PnL di trading kripto: cara hitung laba-rugi belum terealisasi, peran mark price, ROE, dan bedanya dengan realized PnL.","related":[["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures."],["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan."],["liquidation-price","Harga likuidasi (liquidation price)","Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin."],["take-profit","Take profit","Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Mengapa posisi Anda bisa ditutup sebelum margin Anda menyentuh nol?"},"coin":null,"tool":null,"cta":false},"cold-wallet":{"slug":"cold-wallet","cat":"wallets-security","en":"Cold wallet (cold storage)","contentLocale":"id","term":"Cold wallet (cold storage)","aka":["dompet dingin","cold storage","penyimpanan dingin"],"short":"Cold wallet adalah cara menyimpan kripto dengan private key yang dibuat dan disimpan sepenuhnya offline, sehingga tidak bisa dijangkau peretas lewat internet.","body":[["Bentuk cold wallet yang paling umum adalah ",["hardware wallet","hardware-wallet"],", perangkat kecil yang menyimpan kunci di chip khusus. Ada juga paper wallet atau komputer yang tidak pernah terhubung internet. Intinya sama: kunci tidak pernah berada di perangkat online."],["Saat ingin mengirim aset, transaksi disiapkan di perangkat online, ditandatangani di perangkat offline, lalu dikirim ke jaringan. ",["Private key","private-key"]," tidak pernah keluar dari perangkat dingin. Karena itu cold wallet cocok untuk simpanan jangka panjang yang jarang dipindahkan."],["Exchange besar juga menyimpan sebagian besar dana pengguna di cold storage dan hanya menaruh sebagian kecil di ",["hot wallet","hot-wallet"]," untuk penarikan. Untuk Anda sebagai individu, risiko utama cold wallet bukan peretasan online, melainkan kehilangan ",["seed phrase","seed-phrase"],", kerusakan fisik, atau penipuan yang membujuk Anda mengetik seed phrase di ",["situs palsu","phishing"],"."]],"example":["Misalnya Anda memegang 0,2 ",["BTC","bitcoin"]," sebagai tabungan jangka panjang. Anda memindahkannya dari exchange ke hardware wallet dengan biaya penarikan, katakanlah 0,0002 BTC, sehingga tersisa 0,1998 BTC. Seed phrase 24 kata Anda tulis di dua lembar kertas yang disimpan di dua tempat berbeda. Selama tiga tahun Anda tidak menyentuhnya, dan saldo 0,1998 BTC tetap terlihat di block explorer tanpa pernah terhubung ke aplikasi yang tidak dikenal."],"mistakes":["Memotret seed phrase cold wallet dengan ponsel, sehingga kunci justru tersimpan online.","Menyimpan satu-satunya salinan seed phrase di tempat yang rawan banjir atau kebakaran.","Mengetik seed phrase di situs yang mengaku sebagai pembaruan firmware atau sinkronisasi dompet."],"faq":[{"q":"Apa beda cold wallet dan hot wallet?","a":"Hot wallet menyimpan kunci di perangkat online sehingga praktis tetapi lebih rentan. Cold wallet menyimpan kunci secara offline, lebih aman untuk simpanan besar, tetapi kurang praktis untuk transaksi harian."},{"q":"Jika hardware wallet hilang, apakah kripto ikut hilang?","a":"Tidak, selama Anda masih memiliki seed phrase. Anda bisa memulihkan aset di perangkat baru dengan memasukkan seed phrase tersebut."}],"title":"Apa itu cold wallet? Arti cold storage kripto","description":"Pelajari arti cold wallet atau cold storage, cara kerjanya secara offline, dan kesalahan umum saat menyimpan kripto jangka panjang.","related":[["hot-wallet","Hot wallet (dompet panas)","Hot wallet adalah dompet kripto yang private key-nya disimpan di perangkat yang terhubung ke internet, seperti aplikasi ponsel atau ekstensi browser, sehingga praktis untuk transaksi harian."],["hardware-wallet","Hardware wallet (dompet perangkat keras)","Hardware wallet adalah perangkat fisik khusus yang menyimpan private key secara offline dan menandatangani transaksi di dalam perangkat, sehingga kunci tidak pernah terekspos ke komputer atau ponsel."],["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang."],["multisig-wallet","Dompet multisig (multi-signature)","Dompet multisig adalah dompet yang membutuhkan beberapa tanda tangan dari kunci berbeda, misalnya 2 dari 3, sebelum sebuah transaksi bisa dijalankan."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"rug-pull":{"slug":"rug-pull","cat":"wallets-security","en":"Rug pull","contentLocale":"id","term":"Rug pull","aka":["rugpull","rug","kabur bawa dana"],"short":"Rug pull adalah penipuan di mana pengembang proyek kripto tiba-tiba menarik likuiditas, menjual token dalam jumlah besar, atau menyalahgunakan kontrak, sehingga harga token anjlok dan investor tidak bisa keluar.","body":[["Pola yang paling umum terjadi di ",["DEX","dex"],". Pembuat token menyediakan ",["liquidity pool","liquidity-pool"],", misalnya token baru dipasangkan dengan ",["ETH","ethereum"]," atau SOL. Setelah pembeli masuk dan harga naik, pembuat menarik seluruh ",["likuiditas","liquidity"],". Pool kosong, sehingga token yang Anda pegang tidak lagi bisa dijual dengan harga berarti."],["Ada juga bentuk lain: kontrak dengan fungsi tersembunyi yang melarang pembeli menjual (honeypot), pajak jual yang bisa diubah menjadi 99%, atau tim yang memegang sebagian besar suplai lalu menjualnya sekaligus. ",["Memecoin","memecoin"]," baru sangat rawan karena siapa pun bisa membuat token dalam hitungan menit."],"Beberapa hal bisa Anda periksa sebelum membeli: apakah likuiditas dikunci atau dibakar, seberapa besar konsentrasi kepemilikan di beberapa alamat teratas, apakah kontrak sudah diaudit atau terverifikasi, dan apakah owner masih bisa mengubah pajak atau memblokir penjualan. Pemeriksaan ini mengurangi risiko, tetapi tidak menghilangkannya."],"example":"Sebuah token baru diluncurkan dengan pool berisi 20 ETH dan 1 miliar token. Dalam dua hari pembeli menambah 80 ETH ke pool, sehingga pool berisi 100 ETH. Pembuat token yang memegang LP token lalu menarik seluruh likuiditas dan membawa sekitar 100 ETH. Anda yang membeli seharga 2 ETH masih memegang token, tetapi pool yang tersisa hampir kosong, sehingga nilai jualnya mendekati nol.","mistakes":["Membeli token hanya karena ramai di grup Telegram tanpa memeriksa status likuiditas.","Mengabaikan fakta bahwa beberapa alamat memegang sebagian besar suplai token.","Mengira audit menjamin proyek tidak akan melakukan rug pull."],"faq":[{"q":"Bagaimana cara mengecek risiko rug pull?","a":"Periksa apakah likuiditas dikunci, distribusi pemegang token, hak owner di kontrak, dan riwayat tim. Alat pemindai token bisa membantu, tetapi hasilnya tetap perlu dibaca dengan kritis."},{"q":"Apakah dana korban rug pull bisa kembali?","a":"Sangat jarang. Transaksi blockchain tidak bisa dibatalkan, dan pelaku sering anonim. Pemulihan hanya mungkin jika pelaku teridentifikasi dan ada proses hukum."}],"title":"Apa itu rug pull? Arti dan tanda-tanda penipuannya","description":"Pelajari arti rug pull di kripto, bentuk-bentuknya seperti penarikan likuiditas dan honeypot, serta cara memeriksa risikonya.","related":[["memecoin","Memecoin (koin meme)","Memecoin adalah aset kripto yang nilainya terutama digerakkan oleh budaya internet, komunitas, dan tren media sosial, bukan oleh kegunaan teknis atau pendapatan proyek."],["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."],["token-approval","Token approval (izin token)","Token approval adalah izin yang Anda berikan dari dompet kepada smart contract agar kontrak tersebut boleh memindahkan token tertentu milik Anda hingga batas jumlah yang disetujui."],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Ada yang bilang bisa bikin kamu kaya. Lihat dulu apa maunya."},"coin":null,"tool":"/topics/meme-coins","cta":false},"oracle":{"slug":"oracle","cat":"defi","en":"Blockchain oracle","contentLocale":"id","term":"Oracle blockchain","aka":["oracle","oracle harga","price oracle"],"short":"Oracle blockchain adalah layanan yang membawa data dari luar blockchain, seperti harga aset, ke dalam smart contract agar kontrak bisa mengambil keputusan berdasarkan data tersebut.","body":[[["Smart contract","smart-contract"]," tidak bisa membuka situs web atau membaca harga di exchange. Protokol lending perlu tahu harga ",["ETH","ethereum"]," untuk menghitung jaminan, ",["perp DEX","perp-dex"]," perlu ",["harga indeks","index-price"],", dan produk asuransi perlu data peristiwa nyata. Oracle mengumpulkan data dari banyak sumber, menggabungkannya, lalu menuliskannya ke ",["blockchain","blockchain"],"."],["Chainlink adalah jaringan oracle yang paling banyak dipakai. Ada juga Pyth, yang populer di Solana dan banyak perp ",["DEX","dex"],", serta oracle bawaan beberapa protokol yang membaca harga dari pool DEX dengan rata-rata waktu (TWAP)."],"Kualitas oracle sangat menentukan keamanan protokol. Jika oracle hanya membaca satu pool kecil, penyerang bisa memanipulasi harga sementara, misalnya dengan flash loan, lalu meminjam berlebihan atau memicu likuidasi palsu. Oracle yang baik memakai banyak sumber, banyak node, dan batas pembaruan yang jelas. Harga oracle juga bisa sedikit tertinggal dari harga pasar saat pergerakan sangat cepat."],"example":"Misalnya oracle mengambil harga ETH dari 7 sumber: 2.995, 2.998, 3.000, 3.001, 3.002, 3.004, dan 3.350 USD. Angka terakhir berasal dari pool kecil yang sedang dimanipulasi. Oracle memakai median, yaitu nilai tengah 3.001 USD, sehingga harga palsu 3.350 USD tidak berpengaruh. Protokol lending lalu memakai 3.001 USD untuk menghitung nilai jaminan 10 ETH Anda menjadi 30.010 USD.","mistakes":["Mengira harga likuidasi di protokol DeFi selalu sama persis dengan harga di exchange yang Anda pantau.","Memakai protokol yang bergantung pada oracle satu sumber atau satu pool tipis.","Mengabaikan risiko oracle saat menilai keamanan protokol, padahal banyak eksploitasi berawal dari sana."],"faq":[{"q":"Mengapa smart contract membutuhkan oracle?","a":"Karena blockchain tidak bisa mengakses data dari luar jaringannya sendiri. Oracle menjadi jembatan yang menyediakan data seperti harga secara terverifikasi."},{"q":"Apa itu manipulasi oracle?","a":"Serangan di mana harga yang dibaca oracle dibuat menyimpang sementara, sehingga protokol mengambil keputusan berdasarkan harga yang salah, misalnya memberi pinjaman berlebihan."}],"title":"Apa itu oracle blockchain? Fungsi oracle di DeFi","description":"Pelajari arti oracle blockchain, contoh seperti Chainlink dan Pyth, serta mengapa kualitas oracle penting bagi keamanan DeFi.","related":[["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["defi-lending","DeFi lending (pinjam-meminjam DeFi)","DeFi lending adalah layanan pinjam-meminjam kripto lewat smart contract, di mana pemberi pinjaman mendapat bunga dan peminjam harus menyetor jaminan melebihi nilai pinjamannya."],["index-price","Harga indeks (index price)","Harga indeks adalah rata-rata tertimbang harga spot sebuah aset dari beberapa exchange besar, dipakai exchange sebagai acuan untuk mark price, funding rate, dan settlement kontrak futures."],["flash-loan","Flash loan (pinjaman kilat)","Flash loan adalah pinjaman tanpa jaminan di DeFi yang harus dipinjam dan dikembalikan dalam satu transaksi yang sama; jika tidak dilunasi, seluruh transaksi dibatalkan otomatis."]],"lesson":null,"coin":{"slug":"chainlink","name":"Chainlink","symbol":"LINK"},"tool":null,"cta":false},"launchpad":{"slug":"launchpad","cat":"exchange-features","en":"Launchpad (token sale)","contentLocale":"id","term":"Launchpad (penjualan token)","aka":["token sale","IEO","initial exchange offering"],"short":"Launchpad adalah platform penjualan token proyek baru sebelum diperdagangkan di bursa, di mana Anda membeli token dengan harga tetap memakai aset seperti USDT atau token bursa.","body":[["Launchpad di bursa terpusat sering disebut IEO (Initial Exchange Offering). Bursa menyeleksi proyek, lalu pengguna yang memenuhi syarat bisa ikut membeli. Ada juga launchpad on-chain yang berjalan lewat ",["smart contract","smart-contract"]," dan ",["dompet pribadi","non-custodial-wallet"],"."],["Model alokasinya bermacam-macam. Model undian memberi kesempatan berdasarkan jumlah tiket. Model subscription meminta Anda mengunci aset, lalu alokasi dibagi proporsional dan sisa dana dikembalikan. Banyak launchpad mensyaratkan ",["KYC","kyc"]," dan kepemilikan token bursa tertentu."],["Risikonya: permintaan tinggi membuat alokasi kecil, harga bisa jatuh di bawah harga penjualan setelah listing, dan sebagian token mungkin terkunci lewat jadwal vesting. Di launchpad on-chain yang kurang dikenal, risiko proyek palsu atau ",["rug pull","rug-pull"]," lebih tinggi."]],"example":["Misalkan sebuah launchpad menjual 2.000.000 token seharga 0,05 ",["USDT","usdt"],", total 100.000 USDT. Peserta mengunci total 4.000.000 USDT, jadi permintaan 40 kali lipat. Anda mengunci 2.000 USDT, atau 0,05% dari total, sehingga alokasi Anda 1.000 token senilai 50 USDT, dan 1.950 USDT dikembalikan. Jika saat listing harga naik ke 0,08, keuntungan Anda 30 USDT. Jika turun ke 0,03, Anda rugi 20 USDT. Yang paling menentukan hasil adalah ukuran alokasi Anda, bukan hanya harga listing."],"mistakes":["Meminjam dana atau memakai leverage untuk memperbesar alokasi launchpad.","Mengira harga token pasti naik setelah listing.","Ikut launchpad on-chain dari tautan media sosial tanpa memastikan alamat kontrak resmi."],"faq":[{"q":"Apa itu IEO?","a":"IEO adalah penjualan token yang diselenggarakan bursa terpusat. Bursa menangani penjualan dan biasanya langsung melisting token tersebut setelahnya."},{"q":"Kenapa alokasi launchpad saya kecil?","a":"Karena dana yang dikunci peserta jauh lebih besar daripada jumlah token yang dijual. Alokasi dibagi proporsional, sehingga sebagian besar dana Anda dikembalikan."}],"title":"Apa itu launchpad kripto? Arti IEO dan cara ikut","description":"Pahami cara kerja launchpad atau IEO, model alokasi undian dan subscription, serta risiko harga setelah listing.","related":[["launchpool","Launchpool","Launchpool adalah fitur bursa yang memberi Anda token proyek baru secara gratis sebagai imbalan karena mengunci aset tertentu, seperti BNB atau stablecoin, selama periode singkat."],["token-listing","Listing token","Listing token adalah proses ketika bursa menambahkan token baru ke daftar aset yang bisa disetor dan diperdagangkan, biasanya diumumkan lebih dulu beserta jadwal pembukaan setoran dan perdagangan."],["token-unlock","Token unlock","Token unlock adalah saat sejumlah token yang sebelumnya terkunci, misalnya milik tim atau investor awal, dibuka sesuai jadwal vesting sehingga bisa dipindahkan atau dijual."],["airdrop","Airdrop","Airdrop adalah pembagian token gratis oleh sebuah proyek kripto ke alamat dompet tertentu, biasanya untuk pengguna awal, pemegang token tertentu, atau sebagai promosi."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"sub-account":{"slug":"sub-account","cat":"exchange-features","en":"Sub-account","contentLocale":"id","term":"Sub-akun (sub-account)","aka":["sub-account","subakun","akun anak"],"short":"Sub-akun adalah akun tambahan di bawah akun utama bursa yang punya saldo, posisi, dan API key terpisah, sehingga Anda bisa memisahkan strategi atau dana tanpa membuat akun baru dengan KYC lain.","body":[["Akun utama mengelola semua sub-akun: membuat, mentransfer dana antar-akun, dan mengatur izin. Transfer antara akun utama dan sub-akun biasanya gratis dan instan. Jumlah sub-akun yang boleh dibuat dan syaratnya berbeda antarbursa, kadang tergantung ",["level VIP","vip-tier"],"."],["Kegunaan umum: memisahkan trading jangka panjang dan trading ",["leverage","leverage"],", menjalankan bot atau ",["copy trading","copy-trading"]," di akun sendiri, memberi API key khusus dengan izin terbatas, atau mencatat hasil tiap strategi dengan rapi. Karena saldo terpisah, ",["likuidasi","liquidation"]," di satu sub-akun tidak menyentuh saldo di akun lain."],["Jaga keamanan akun utama dengan ",["autentikasi dua faktor","two-factor-authentication"],", karena siapa pun yang menguasainya bisa mengakses semua sub-akun. Sub-akun tidak boleh dipakai untuk orang lain; semuanya tetap tercatat atas identitas ",["KYC","kyc"]," Anda."]],"example":"Misalkan Anda punya 10.000 USDT. Anda menyimpan 7.000 di akun utama untuk spot, lalu mentransfer 2.000 ke sub-akun A untuk futures dan 1.000 ke sub-akun B untuk bot grid. Suatu malam, posisi futures di sub-akun A dengan cross margin terkena likuidasi dan kehilangan seluruh 2.000 USDT. Kerugian berhenti di situ: 7.000 di akun utama dan 1.000 di sub-akun B tetap aman. Jika semuanya ada di satu akun cross margin, seluruh 10.000 USDT bisa ikut menanggung kerugian itu.","mistakes":["Memberikan akses sub-akun kepada orang lain untuk dikelola.","Memberi API key sub-akun izin penarikan padahal hanya butuh izin trading.","Lupa mengamankan akun utama yang mengendalikan semua sub-akun."],"faq":[{"q":"Apakah sub-akun perlu KYC terpisah?","a":"Umumnya tidak, karena sub-akun mengikuti identitas akun utama. Kebijakan dan jumlah maksimal sub-akun berbeda di setiap bursa."},{"q":"Apakah transfer ke sub-akun dikenai biaya?","a":"Transfer internal antara akun utama dan sub-akun biasanya gratis dan instan. Cek halaman bantuan bursa jika ada batas tertentu."}],"title":"Apa itu sub-akun di bursa kripto? Fungsi dan cara pakai","description":"Pahami fungsi sub-akun di bursa kripto untuk memisahkan strategi, membatasi risiko likuidasi, dan mengatur API key.","related":[["unified-trading-account","Akun trading terpadu (Unified Trading Account)","Akun trading terpadu adalah jenis akun bursa yang menggabungkan saldo spot, margin, futures, dan opsi dalam satu dompet, sehingga satu pool aset bisa dipakai sebagai margin untuk berbagai produk."],["isolated-margin","Margin terisolasi (isolated margin)","Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut."],["two-factor-authentication","Autentikasi dua faktor (2FA)","Autentikasi dua faktor (2FA) adalah lapisan keamanan yang meminta bukti kedua selain kata sandi, misalnya kode dari aplikasi autentikator atau kunci keamanan fisik, sebelum Anda bisa login atau menarik dana."],["copy-trading","Copy trading","Copy trading adalah fitur bursa yang otomatis meniru posisi trader lain, yang biasa disebut lead trader, ke akun Anda sesuai modal dan pengaturan yang Anda pilih."]],"lesson":null,"coin":null,"tool":null,"cta":false},"vip-tier":{"slug":"vip-tier","cat":"exchange-features","en":"VIP fee tier","contentLocale":"id","term":"Level VIP (tingkat biaya VIP)","aka":["VIP tier","VIP level","tier biaya"],"short":"Level VIP adalah tingkatan biaya trading di bursa kripto yang ditentukan oleh volume perdagangan 30 hari, saldo aset, atau kepemilikan token bursa, di mana level lebih tinggi mendapat biaya maker dan taker lebih rendah.","body":["Hampir semua bursa besar memakai sistem bertingkat. Pengguna baru mulai dari level reguler. Jika volume spot atau futures dalam 30 hari melewati batas tertentu, atau saldo aset di akun mencapai nilai tertentu, level naik dan biaya turun. Batas dan tarif tiap level berbeda per bursa dan per produk.","Selain biaya lebih murah, level tinggi bisa memberi batas penarikan lebih besar, limit API lebih tinggi, manajer akun, atau akses produk tertentu. Banyak bursa mengevaluasi level setiap hari berdasarkan data 30 hari terakhir, sehingga level bisa turun lagi jika volume menurun.","Bagi trader ritel, perbedaan level awal sering kecil. Namun bagi trader aktif bervolume besar, selisih beberapa basis poin bisa berarti banyak. Hitung apakah mengejar level layak, jangan menambah trading hanya untuk naik level."],"example":["Misalkan di level reguler biaya taker futures 0,05%, dan level 1 membutuhkan volume 30 hari sebesar 5.000.000 ",["USDT","usdt"]," dengan biaya taker 0,04%. Jika volume Anda 4.000.000 USDT per bulan, biaya Anda 2.000 USDT. Di level 1 dengan volume yang sama, biayanya 1.600 USDT, hemat 400. Tetapi untuk naik level Anda perlu tambahan volume 1.000.000 USDT, yang memakan biaya sekitar 500 USDT di tarif reguler, plus risiko dari trading tambahan. Dalam kasus ini, mengejar level justru lebih mahal."],"mistakes":["Menambah trading yang tidak perlu hanya untuk naik level VIP.","Mengira level VIP berlaku permanen, padahal dievaluasi ulang secara berkala.","Membandingkan biaya bursa hanya di level reguler tanpa melihat level yang benar-benar Anda capai."],"faq":[{"q":"Bagaimana cara naik level VIP?","a":"Biasanya dengan meningkatkan volume trading 30 hari, menambah saldo aset, atau memegang token bursa, tergantung aturan bursa. Syarat lengkapnya tercantum di halaman biaya resmi bursa."},{"q":"Apakah level VIP bisa turun?","a":"Bisa. Banyak bursa mengevaluasi level setiap hari berdasarkan data 30 hari terakhir, sehingga level turun jika volume atau saldo Anda berkurang."}],"title":"Apa itu level VIP di bursa kripto? Tingkat biaya","description":"Pelajari cara kerja level VIP dan tier biaya di bursa kripto, syarat naik level, dan cara menghitung apakah layak dikejar.","related":[["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada."],["referral-code","Kode referral (rebate biaya)","Kode referral adalah kode undangan yang Anda masukkan saat mendaftar di bursa kripto, yang dapat memberi Anda potongan atau pengembalian sebagian biaya trading (rebate) sesuai program bursa tersebut."],["trading-volume","Volume trading (trading volume)","Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar."],["market-maker","Market maker","Market maker adalah pihak yang terus-menerus memasang order beli dan jual di dekat harga pasar sehingga trader lain selalu punya lawan transaksi, dan ia mendapat keuntungan dari selisih spread."]],"lesson":null,"coin":null,"tool":"/rates","cta":false},"token-listing":{"slug":"token-listing","cat":"exchange-features","en":"Token listing","contentLocale":"id","term":"Listing token","aka":["token listing","listing koin","koin baru listing"],"short":"Listing token adalah proses ketika bursa menambahkan token baru ke daftar aset yang bisa disetor dan diperdagangkan, biasanya diumumkan lebih dulu beserta jadwal pembukaan setoran dan perdagangan.","body":[["Bursa menilai proyek sebelum listing, misalnya dari sisi teknologi, tim, ",["likuiditas","liquidity"],", kepatuhan, dan permintaan pengguna. Pengumuman listing biasanya memuat waktu buka setoran, waktu mulai perdagangan, pasangan yang tersedia, dan jaringan token yang didukung. Kadang token juga masuk lewat ",["launchpool","launchpool"]," atau ",["launchpad","launchpad"]," sebelumnya."],["Di menit-menit awal perdagangan, harga sering sangat volatil. ",["Order book","order-book"]," masih tipis, ",["slippage","slippage"]," besar, dan bursa kadang membatasi jenis order atau harga di awal. Banyak penerima ",["airdrop","airdrop"]," dan peserta launchpool menjual saat itu, sehingga tekanan jual bisa tinggi."],"Listing di bursa besar meningkatkan likuiditas, tetapi tidak menjamin harga naik. Penipu sering memakai kabar listing palsu atau token tiruan dengan nama sama. Cek pengumuman di kanal resmi bursa dan alamat kontrak yang tercantum."],"example":"Misalkan token baru mulai diperdagangkan pukul 15.00 WIB. Anda memasang market order beli senilai 500 USDT di detik pertama, saat harga terakhir 1,00 USDT. Karena order book tipis, order Anda menghabiskan beberapa tingkat ask hingga 1,12, dengan harga rata-rata 1,06. Anda mendapat sekitar 471 token, bukan 500. Sepuluh menit kemudian harga turun ke 0,90, sehingga nilai posisi Anda sekitar 424 USDT, rugi 76. Memakai limit order akan membatasi harga yang Anda bayar.","mistakes":["Memakai market order di detik pertama listing saat order book masih tipis.","Percaya kabar listing dari grup media sosial tanpa mengecek pengumuman resmi bursa.","Membeli token tiruan dengan nama sama karena tidak mengecek alamat kontrak."],"faq":[{"q":"Apakah harga token pasti naik setelah listing?","a":"Tidak. Banyak token naik sesaat lalu turun karena penerima airdrop dan investor awal menjual. Pergerakan awal sering sangat volatil ke dua arah."},{"q":"Di mana melihat jadwal listing resmi?","a":"Di halaman pengumuman resmi bursa atau aplikasi bursa. Hindari tautan dari pesan pribadi yang mengaku memberi info listing lebih awal."}],"title":"Apa itu listing token? Arti koin baru listing di bursa","description":"Pelajari proses listing token di bursa kripto, kenapa harga awal sangat volatil, dan cara menghindari token tiruan.","related":[["delisting","Delisting","Delisting adalah keputusan bursa untuk menghapus token atau pasangan perdagangan dari platformnya, sehingga perdagangan dihentikan dan pengguna diberi batas waktu untuk menarik aset."],["launchpool","Launchpool","Launchpool adalah fitur bursa yang memberi Anda token proyek baru secara gratis sebagai imbalan karena mengunci aset tertentu, seperti BNB atau stablecoin, selama periode singkat."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["altcoin","Altcoin","Altcoin adalah sebutan untuk semua aset kripto selain Bitcoin, mulai dari jaringan besar seperti Ethereum dan Solana hingga token kecil yang baru diluncurkan."]],"lesson":null,"coin":null,"tool":"/activities","cta":false},"stock-perpetuals":{"slug":"stock-perpetuals","cat":"tokenized-assets","en":"Stock perpetuals","contentLocale":"id","term":"Perpetual saham (stock perpetuals)","aka":["stock perpetuals","stock perps","perpetual saham"],"short":"Perpetual saham adalah kontrak berjangka perpetual tanpa tanggal jatuh tempo yang mengikuti harga saham atau indeks saham, diperdagangkan dengan margin dan leverage di bursa kripto atau perp DEX.","body":[["Cara kerjanya sama dengan ",["perpetual","perpetual-futures"]," ",["BTC","bitcoin"],": Anda membuka posisi long atau short dengan margin ",["USDT","usdt"],", tanpa memiliki saham. Harga kontrak dijaga dekat dengan harga acuan lewat ",["funding rate","funding-rate"]," yang dibayar antara pihak long dan short secara berkala."],"Tantangan khususnya adalah jam pasar. Saham hanya diperdagangkan di jam bursa, sedangkan kontrak bisa diperdagangkan lebih lama. Di luar jam pasar, harga acuan bisa tidak bergerak, sehingga harga kontrak ditentukan oleh trader sendiri dengan aturan khusus yang berbeda per platform. Saat pasar saham dibuka kembali, bisa terjadi lompatan harga atau gap.",["Gap inilah risiko terbesar. Posisi berleverage bisa langsung melewati harga ",["stop loss","stop-loss"]," dan terkena ",["likuidasi","liquidation"],". Cek spesifikasi kontrak: sumber harga indeks, jam perdagangan, leverage maksimal, dan interval funding rate."]],"example":"Misalkan Anda membuka long perpetual sebuah saham teknologi di harga 400 USDT, ukuran posisi 2.000 USDT dengan margin 200 USDT, jadi leverage 10x. Jumat sore pasar saham tutup di 400. Selama akhir pekan perusahaan mengumumkan kabar buruk, dan Senin pagi saham dibuka di 360, turun 10%. Kerugian Anda sekitar 200 USDT, seluruh margin, dan posisi sudah terlikuidasi sebelum stop loss di 385 sempat terisi. Dengan leverage 3x, penurunan yang sama hanya akan memakan sekitar 30% dari margin.","mistakes":["Membiarkan posisi berleverage tinggi terbuka melewati akhir pekan atau pengumuman laba.","Mengira stop loss pasti terisi di harga yang dipasang saat pasar membuka dengan gap.","Tidak membaca jam perdagangan dan aturan harga di luar jam pasar."],"faq":[{"q":"Apakah perpetual saham memberi kepemilikan saham?","a":"Tidak. Ini hanya kontrak derivatif yang mengikuti harga, tanpa hak dividen atau hak suara."},{"q":"Kenapa perpetual saham berisiko saat akhir pekan?","a":"Karena pasar saham tutup dan berita bisa membuat harga pembukaan berikutnya melompat. Lompatan itu bisa memicu likuidasi sebelum stop loss sempat dijalankan."}],"title":"Apa itu stock perpetuals? Perpetual saham di kripto","description":"Pahami cara kerja perpetual saham, funding rate, risiko gap saat pasar saham dibuka, dan bedanya dengan saham tokenisasi.","related":[["tokenized-stocks","Saham tokenisasi (tokenized stocks)","Saham tokenisasi adalah token di blockchain yang mewakili atau mengikuti harga saham nyata, seperti saham perusahaan AS, sehingga bisa diperdagangkan di platform kripto, sering 24 jam."],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
